INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 13, 'Job’s social integrity.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 14, 'God rises up. Judges in favor of the oppressed (Ps. 76:9).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 20, 'blessed me. He was grateful to me.');
