INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 24, 'Job put God first—the basis of integrity.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 24, 'my hope. Or “my security.”');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 26, 'Worshiping heavenly bodies is condemned in Deut. 4:19; 17:2–5.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 28, 'denied God. The practice of idolatry denies the true God.');
