INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 34, 'feared the great multitude. Fear of public gossip. contempt of families. Popular scorn. go out of the door. Avoiding criticism.');
