INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 36, 'on my shoulder. With a sense of pride.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 37, 'number of my steps. All Job’s actions. approach Him. Job still longs for a meeting with his God (23:3–7).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 31, 38, 'land cries out. The reason for the land’s complaint is given in v. 39: unethical farming practices.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 1, 'Introduction and four speeches by Elihu.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 1, 'Introduction and four speeches by Elihu.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 1, 'Elihu’s absurd self-introduction is perhaps the result of his nervousness.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 1, 'his own eyes. Or, “his own opinion.”');
