INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 17, 'answer my part. To do my part to help Job.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 18, 'Elihu calls himself a bag of wind.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 32, 22, 'take me away. To destroy me.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 1, 'First Elihu speech with long introduction (vv. 1–7).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 4, 'See note on 4:9.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 5, 'If you can answer me. A challenge.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 6, 'Since Job finds God overwhelming (31:23), Elihu will be the human advocate Job longs for (9:32–35).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 8, 'you have spoken … I have heard. Elihu claims to quote Job.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 9, 'I am pure. Job has not said this; see also Zophar (11:4).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 10, 'occasions. Excuses for attacking.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 11, 'stocks. See note on 13:27. watches all my paths. Restating Job’s remark (7:12; 31:4).');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 12, 'not righteous. Or, not correct. God is greater. God owes no one explanations.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 14, 'Discipline by God who is sovereign.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 15, 'dream … vision of the night. Like Zophar and Bildad (11:10; 25:4–6), Elihu goes back to Eliphaz (4:12–13).');
