INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 18, 'keeps back his soul from the Pit. Saves him from death (major emphasis with Elihu—vv. 22, 24, 28, 30). Job must know what God is really saving him from.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 19, 'See Job’s words, 30:16–19. Elihu believes Job’s affliction is divine.');
