INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 25, 'return. To recover youthful vigor.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 26, 'restores to man His righteousness. Leads him back to right living.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 33, 27, 'says. The Hebrew says “sings.”');
