INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 1, 'Elihu’s last speech is interrupted by the storm of God’s arrival.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 1, 'Elihu’s last speech is interrupted by the storm of God’s arrival.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 2, 'Bear with me. Elihu may have difficulty holding respectful attention. Eleven times he says “please listen” or its equivalent.');
