INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 13, 'hypocrites in heart. A description of thoroughly godless people. store up wrath. Either theirs or God’s or both. binds them. God disciplines them.');
