INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 18, 'take you away with one blow. The Hebrew says, “entice you through abundance.”');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 36, 20, 'Do not desire the night. Neither riches, nor power, nor darkness will help.');
