INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 37, 16, 'clouds are balanced. Clouds in the sky hang and float.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Andrews Study Bible', 'Jó', 37, 17, 'garments hot. Can you explain the desert winds’ suffocating heat?');
